TenantAppManagement = {
    init: async function (app, container, tenant) {
        app = app || session.app;
        container = container || $(".component[name=TenantAppManagement]");
        if (!tenant)
            return;

        
        TenantAppManagement.buildAppGrid(container, app, tenant);
    },

    add: async function(e, tenant, app, appGrid) {
        e.preventDefault();

        var domainSuffix = app.Config.CRM.EnvironmentUrlSuffix || location.hostname.split('.').slice(-3).join('.');

        var d = new EditorDialog({
            title: "[resource_displayname[addapp]]",
            confirm: "<span class='k-icon k-i-plus'></span>[resource_displayname[add]]",
            data: {
                Name: tenant.Name,
                CompanyName: '',
                Domain: `.${domainSuffix}`,
                SourceAppId: 0,
                Password: ""
            },
            fields: [
                { field: "Name", title: "[resource_displayname[name]]" },
                { field: "CompanyName", title: "[resource_displayname[companyname]]" },
                { field: "SourceAppId", title: "[resource_displayname[sourceappid]]" },
                { field: "Password", title: "[resource_displayname[password]]", fieldType: "password" }
            ]
        });
        d.events.confirm = () => TenantAppManagement.buildPortal(d, app, tenant, appGrid);
        d.init();
        let ds = await model.getDatasource({ endpoint: "ContentManagement/App" });
        $("input[name=SourceAppId]", d.element).kendoDropDownList({
            optionLabel: "[resource_displayname[noSourceApp]]",
            dataTextField: "Name",
            dataValueField: "Id",
            dataSource: ds
        });
    },

    buildAppGrid: async function (container, app, tenant) {
        var appData = await model.getDatasource({ endpoint: "ContentManagement/App", odataAppend: "?$filter=TenantId eq '" + tenant.Id + "'" });
        var appGrid = new GridWidget(container, appData);
        appGrid.toolbar = "<button class='btn btn-sm btn-primary' name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>";
        appGrid.groupable = false;
        appGrid.pageable = false;
        appGrid.filterable = true;
        appGrid.editable = false;
        appGrid.columns = [
            { field: "Name", title: "[resource_shortdisplayname[Name]]" },
            { field: "Domain", title: "[resource_shortdisplayname[Domain]]" },
        ];
        await appGrid.init();
        $("[name=add]", appGrid.gridElement).on("click", (e) =>  TenantAppManagement.add(e, tenant, app, appGrid));
    },

    buildPortal: async function(d, app, tenant, appGrid){
        notification.info("[resource_displayname[creatingapp]]");

        if(d.data.SourceAppId == 0) {
            await TenantAppManagement.buildEmptyPortal(d, app, tenant, appGrid);
            return;
        }

        var newApi = await TenantAppManagement.createNewApp(d, tenant);
        await TenantAppManagement.createDMSFolders(newApi);
        await TenantAppManagement.importPackages(d, newApi);
        await TenantAppManagement.setupConfig(d, tenant, newApi);
        await TenantAppManagement.unpackContentFolder(newApi, tenant, d.data.SourceAppId);
        await TenantAppManagement.linkAdmins(app, newApi);
        var ssoUser = await TenantAppManagement.createBuyerAdminAccount(newApi, d.data.Name);
        await TenantAppManagement.createRootBucket(newApi, tenant);
        await TenantAppManagement.copyWorkflowsTriggersAndSchedules(newApi, ssoUser.id, d.data.SourceAppId);
        notification.success("[resource_displayname[created]]");
        appGrid.refresh();
        d.events.close();
    },

    buildEmptyPortal: async function(d, app, tenant, appGrid) {
        var newApi = await TenantAppManagement.createNewEmptyApp(d, tenant);
        notification.success("[resource_displayname[created]]");
        appGrid.refresh();
        d.events.close();
    },

    importPackages: async function (d, newApi) {
        var packages = (await api.get("ContentManagement/App(" + d.data.SourceAppId + ")/Export()?$expand=Items")).value;
        for (let i = 0; i < packages.length; i++) {
            await newApi.post("Packaging/Package/ImportThis?appId=" + newApi.app.Id, [packages[i]]);
        };
    },

    createNewApp: async function (d, tenant) {
        var sourceApp = await api.get("ContentManagement/App(" + d.data.SourceAppId + ")?$expand=Cultures");

        var config = JSON.parse(sourceApp.ConfigJson);

        var newApp = await api.post("ContentManagement/App", {
            TenantId: tenant.Id,
            Domain: d.data.Name.toLowerCase().replaceAll(' ', '-') + d.data.Domain,
            Name: d.data.Name,
            ConfigJson: JSON.stringify(config, null, 4),
            DefaultTheme: sourceApp.DefaultTheme,
            DefaultCultureId: sourceApp.DefaultCultureId,
            Cultures: sourceApp.Cultures.map(c => ({
                CultureId: c.CultureId
            }))
        });
        var newApi = new Api({ apiRoot: "https://" + newApp.Domain + "/Api/" });
        newApi.app = newApp;
        await newApi.login(session.user, d.data.Password, true);
        return newApi;
    },

    createNewEmptyApp: async function(d, tenant) {
        var newApp = await api.post("ContentManagement/App", {
            TenantId: tenant.Id,
            Domain: d.data.Name.toLowerCase().replaceAll(' ', '-') + d.data.Domain,
            Name: d.data.Name,
            ConfigJson: JSON.stringify({
                "Themes": {
                    "Default": {}
                }
            }, null, 4),
            DefaultTheme: 'Default',
            DefaultCultureId: '',
            Cultures: []
        });
        var newApi = new Api({ apiRoot: "https://" + newApp.Domain + "/Api/" });
        newApi.app = newApp;
        await newApi.login(session.user, d.data.Password, true);
        return newApi;
    },

    createDMSFolders: async function (newApi) {
        await newApi.post("DMS/Data/Transactions/Received");
        await newApi.post("DMS/Data/Transactions/Processed");
        await newApi.post("DMS/Data/Transactions/Transformed");
        await newApi.post("DMS/Data/Masterdata/Received");
        await newApi.post("DMS/Data/Masterdata/Processed");
        await newApi.post("DMS/Data/Masterdata/Transformed");
        await newApi.post("DMS/Content/Flags");
        await newApi.post("DMS/Content/Slideshow");
                    },

    unpackContentFolder: async function (newApi, tenant, sourceAppId) {
        var app = await api.get("ContentManagement/App(" + sourceAppId + ")");

        try {
            var blob = await new Promise(function (resolve, reject) {
                var sourceReq = new XMLHttpRequest();
                sourceReq.open("GET", window.location.protocol + "//" + app.Domain + "/Api/DMS/Content" + "?t=" + session.token, true);
                sourceReq.setRequestHeader("Authorization", "bearer " + session.token);
                sourceReq.responseType = "blob";
                sourceReq.onload = function (oEvent) {
                    if (this.readyState === 4 && this.status >= 200 & this.status <= 300) {
                        resolve(this.response);
                    } else {
                        reject(this.status);
                    }
                };
                sourceReq.send();
            });
        } catch(error) {
            console.log(error);
            notification.error('[resource_displayname[failedToPackDmsContent]]');
        }

        try {
            await new Promise(function (resolve, reject) {
                var destReq = new XMLHttpRequest();
                destReq.open("PUT", newApi.apiRoot + "DMS/?unpack" , true);
                destReq.setRequestHeader("Authorization", "bearer " + newApi.token);
                destReq.setRequestHeader("Content-Type", "application/zip");
                destReq.onload = function (oEvent) {
                    if (this.readyState === 4 && this.status >= 200 && this.status <= 300) {
                        resolve(this.response);
                    } else {
                        reject(this.status);
                    }
                };
                destReq.send(blob);
            });
        } catch(error) {
            console.log(error);
            notification.error('[resource_displayname[failedToUnpackDmsContent]]');
        }

        try {
            var blob = await new Promise(function (resolve, reject) {
                var sourceReq = new XMLHttpRequest();
                sourceReq.open("GET", "/Api/DMS/CRM/" + tenant.Id + "/Theme/Content" + "?t=" + session.token, true);
                sourceReq.setRequestHeader("Authorization", "bearer " + session.token);
                sourceReq.responseType = "blob";
                sourceReq.onload = function (oEvent) {
                    if (this.readyState === 4 && this.status >= 200 & this.status <= 300) {
                        resolve(this.response);
                    } else {
                        reject(this.status);
                    }
                };
                sourceReq.send();
            });
        } catch(error) {
            console.log(error);
            notification.error('[resource_displayname[failedToPackThemeContent]]');
        }

        try {
            await new Promise(function (resolve, reject) {
                var destReq = new XMLHttpRequest();
                destReq.open("PUT", newApi.apiRoot + "DMS/?unpack" , true);
                destReq.setRequestHeader("Authorization", "bearer " + newApi.token);
                destReq.setRequestHeader("Content-Type", "application/zip");
                destReq.onload = function (oEvent) {
                    if (this.readyState === 4 && this.status >= 200 && this.status <= 300) {
                        resolve(this.response);
                    } else {
                        reject(this.status);
                    }
                };
                destReq.send(blob);
            });
        } catch(error) {
            console.log(error);
            notification.error('[resource_displayname[failedToUnpackThemeContent]]');
        }
    },

    linkAdmins: async function(app, newApi){
        var admins = await api.get("AppSecurity/UserRole?$filter=Role/AppId eq " + app.Id + "and Role/Name eq 'Administrators' and UserId ne '" + session.user + "'");
        var adminRole = (await api.get("AppSecurity/Role?$filter=AppId eq " + newApi.app.Id + " and Name eq 'Administrators'")).value[0];
        var userRole = (await api.get("AppSecurity/Role?$filter=AppId eq " + newApi.app.Id + " and Name eq 'Users'")).value[0];
        var adminRoleId = adminRole.Id;
        var userRoleId = userRole.Id;
        for (let i = 0; i < admins.value.length; i++){
            var adminEntry = admins.value[i];
            await newApi.post("AppSecurity/UserRole", {
                UserId: adminEntry.UserId,
                RoleId: adminRoleId
            });
            await newApi.post("AppSecurity/UserRole", {
                UserId: adminEntry.UserId,
                RoleId: userRoleId
            });
        }
    },

    createBuyerAdminAccount: async function (newApi, appName) {
        var ssoUser = await newApi.register({
            DisplayName: appName + ".admin",
            Email: appName.replaceAll(' ', '') + ".admin@' + (newApi.app.Domain || location.hostname)",
            Password: Guid().replaceAll("-", "") + "A!",
            Culture: newApi.app.DefaultCultureId,
            PhoneNumber: "",
            AppId: newApi.app.Id
        });
        var userId = ssoUser.id;
        var appInfo = await newApi.get("ContentManagement/App(" + newApi.app.Id + ")?$select=ConfigJson");
        /* b2b onboarding */
        var config = JSON.parse(appInfo.ConfigJson);
        var rootBucketId = config.B2B.RootBucket;
        var buyerAdminRoleId = (await newApi.get("B2B/BucketRole?$filter=Bucket/ParentId eq " + rootBucketId + " and (contains(Role/Name, 'Buyer') or contains(Role/Name, 'Debtor'))")).value[0].RoleId;
        var userIsBuyerAdmin = (await newApi.get(`B2B/B2BUserRole?$filter=UserId eq '${userId}' and RoleId eq ${buyerAdminRoleId}`)).value.length > 0;
        if(!userIsBuyerAdmin)
            await newApi.post("B2B/B2BUserRole", {
                UserId: userId,
                RoleId: buyerAdminRoleId
            }).catch((err) => error(err));
        
        /* core onboarding */
        var coreBuyerRoleId = (await newApi.get("AppSecurity/Role?$filter=contains(Name, 'Buyer') and AppId eq " + newApi.app.Id)).value[0].Id;
        await newApi.post("AppSecurity/UserRole", {
            UserId: userId,
            RoleId: coreBuyerRoleId
        }).catch((err) => error(err));

        var coreAdminRoleId = (await newApi.get("AppSecurity/Role?$filter=contains(Name, 'Admin') and AppId eq " + newApi.app.Id)).value[0].Id;
        await newApi.post("AppSecurity/UserRole", {
            UserId: userId,
            RoleId: coreAdminRoleId
        }).catch((err) => error(err));

        notification.success("[resource_displayname[adminusercreated]]");

        return ssoUser;
    },

    copyWorkflowsTriggersAndSchedules: async function(newApi, userId, sourceAppId) {
        var transactionsReceivedEvents = (await api.get(`Workflow/WorkflowEvent?$expand=Flow&$filter=Type eq 'DocumentManagement/File' and EventContext eq 'App(${sourceAppId})/DMS(File_Created)/data/transactions/received'`)).value;
        var masterdataReceivedEvents = (await api.get(`Workflow/WorkflowEvent?$expand=Flow&$filter=Type eq 'DocumentManagement/File' and EventContext eq 'App(${sourceAppId})/DMS(File_Created)/data/masterdata/received'`)).value;
        var scheduledTasks = (await api.get(`Scheduling/ScheduledTask?$filter=AppId eq ${sourceAppId}&$expand=Flow`)).value;
        var appWorkflows = (await api.get(`Workflow/FlowDefinition?$filter=AppId eq ${newApi.app.Id}`)).value;

        for(var event of transactionsReceivedEvents) {
            var matchedFlow = appWorkflows.filter(wf => wf.Name == event.Flow.Name)[0];

            if(matchedFlow) {
                await newApi.post('Workflow/WorkflowEvent', {
                    Type: "DocumentManagement/File",
                    EventContext: "App(" + newApi.app.Id + ")/DMS(File_Created)/data/transactions/received",
                    FlowId: matchedFlow.Id,
                    ExecuteAs: userId
                });
            }
        }

        for(var event of masterdataReceivedEvents) {
            var matchedFlow = appWorkflows.filter(wf => wf.Name == event.Flow.Name)[0];

            if(matchedFlow) {
                await newApi.post('Workflow/WorkflowEvent', {
                    Type: "DocumentManagement/File",
                    EventContext: "App(" + newApi.app.Id + ")/DMS(File_Created)/data/masterdata/received",
                    FlowId: matchedFlow.Id,
                    ExecuteAs: userId
                });
            }
        }

        for(var task of scheduledTasks) {
            var matchedFlow = appWorkflows.filter(wf => wf.Name == task.Flow.Name)[0];

            if(matchedFlow) {
                await newApi.post('Scheduling/ScheduledTask', {
                    AppId: newApi.app.Id,
                    FlowId: matchedFlow.Id,
                    Name: task.Name,
                    Description: task.Description,
                    ExecutionArgs: task.ExecutionArgs,
                    ScheduleInTicks: task.ScheduleInTicks,
                    ExecuteAs: userId,
                    NextExecution: task.NextExecution
                });
            }
        }
    },

    createRootBucket: async function (newApi, tenant) {
        var existing = (await api.get(`B2B/Bucket?$filter=Path eq '${tenant.Name}'`)).value[0];
        if(existing == null) {
            var rootBucket = await newApi.post('B2B/Bucket/AddClientRoot?name=' + tenant.Name + '&description=Root bucket for ' + newApi.app.Domain + '&sourceSystems=' + tenant.Name);
            
            await TenantAppManagement.linkAdminsToRootBucket(newApi, rootBucket.Id);
        } else {
            /*var types = [
                { key: 'DebtorGroup', name: 'Buyers' },
                { key: 'CreditorGroup', name: 'Suppliers' },
                { key: 'FunderGroup', name: 'Funders' }
            ];

            for(var i = 0; i < types.length; i++) {
                var t = types[i];

                await api.post('B2B/Bucket', {
                    Path: `${existing.Path}/${companyName}-${t.key}-${t.name}`,
                    ParentId: existing.Id,
                    Name: `${companyName} ${t.name} Group`,
                    Description: `${t.name} Group for ${companyName}`,
                    Key: t.key,
                });
            }*/
        }

        var config = JSON.parse(newApi.app.ConfigJson);
        config.B2B.RootBucket = existing != null
            ? existing.Id
            : rootBucket.Id;
        newApi.app.ConfigJson = JSON.stringify(config, null, 4);
        await newApi.update("ContentManagement/App(" + newApi.app.Id + ")", newApi.app);
    },

    linkAdminsToRootBucket: async function (newApi, rootBucketId) {
        var bucketAdminRole = (await newApi.get("B2B/BucketRole?$filter=BucketId eq " + rootBucketId + " and contains(Role/Name, 'Bucket Admins')")).value[0];
        var admins = await api.get("AppSecurity/UserRole?$filter=Role/AppId eq " + newApi.app.Id + "and Role/Name eq 'Administrators' and UserId ne '" + session.user + "'");
        var bucketAdminRoleId = bucketAdminRole.RoleId;
        for (let i = 0; i < admins.value.length; i++) {
            var adminEntry = admins.value[i];
            await newApi.post("B2B/B2BUserRole", { UserId: adminEntry.UserId, RoleId: bucketAdminRoleId });
        }
    },

    createSourceSystem: async function (newApi, rootBucketId, tenant){
        var systemExists = await newApi.get("B2B/System?$filter=Id eq '" + tenant.Name + "'");
        if (systemExists.value.length == 0) {
            await newApi.post("B2B/System", {
                Name: tenant.Name,
                Description: tenant.Name,
                Id: tenant.Name
            });
        }
        await newApi.post("B2B/BucketSystem", {BucketId: rootBucketId, SystemId: tenant.Name});
    },

    setupConfig: async function (d, tenant, newApi) {
        var sourceApp = await api.get("ContentManagement/App(" + d.data.SourceAppId + ")");
        var config = JSON.parse(sourceApp.ConfigJson);
        var calendar = (await api.get("Scheduling/Calendar?$filter=AppId eq " + newApi.app.Id)).value[0];
        if(calendar != null)
            config.Calendars.primary = calendar.Id;
        else {
            var calendar = {
                Id: 0,
                AppId: newApi.app.Id,
                Name: 'primary'
            };

			await newApi.add("Scheduling/Calendar", calendar).then(async (calendarCreated) => {
                config.Calendars[calendarCreated.Name] = calendarCreated.Id;
                newApi.app.ConfigJson = JSON.stringify(config);
                await newApi.put("ContentManagement/App(" + newApi.app.Id + ")", newApi.app)
                    .catch((err) => error(err));
            }).catch((err) => error(err));
        }
        
        config.B2B.SourceSystem = tenant.Name;
        config.B2B.TransactionSource = tenant.Name;
        var domainName = newApi.app.Domain.split(".")[0];
        config.Deployment = {\r\n            "Targets": [],\r\n            "DMS": [\r\n                "Content",\r\n                "Content/Flags",\r\n                "Content/Slideshow"\r\n            ],\r\n            "TenantId": tenant.Id\r\n        },\r\n        newApi.app.ConfigJson = JSON.stringify(config, null, 4);
        await api.put("ContentManagement/App(" + newApi.app.Id + ")", newApi.app);
    },
}
